%options case-insensitive

// Special states for recognizing aliases
// A special state for grabbing text up to the first comment/newline
%x ID ALIAS LINE CONFIG CONFIG_DATA

%x acc_title
%x acc_descr
%x acc_descr_multiline
%%

[\n]+                                                           return 'NEWLINE';
\s+                                                             /* skip all whitespace */
<ID,ALIAS,LINE>((?!\n)\s)+                                      /* skip same-line whitespace */
<INITIAL,ID,ALIAS,LINE>\#[^\n]*   															/* skip comments */
\%%(?!\{)[^\n]*                                                 /* skip comments */
[^\}]\%\%[^\n]*                                                 /* skip comments */
([0-9]+(\.[0-9]{1,2})?|\.[0-9]{1,2})(?=[ \n]+)    				return 'NUM';
<ID>\@\{                                                        { this.begin('CONFIG'); return 'CONFIG_START'; }

| signal 'NEWLINE'
| autonumber NUM NUM 'NEWLINE' { $$= {type:'sequenceIndex',sequenceIndex: Number($2), sequenceIndexStep:Number($3), sequenceVisible:true, signalType:yy.LINETYPE.AUTONUMBER};}
| autonumber NUM 'NEWLINE' { $$ = {type:'sequenceIndex',sequenceIndex: Number($2), sequenceIndexStep:1, sequenceVisible:true, signalType:yy.LINETYPE.AUTONUMBER};}
| autonumber off 'NEWLINE' { $$ = {type:'sequenceIndex', sequenceVisible:false, signalType:yy.LINETYPE.AUTONUMBER};}
| autonumber 'NEWLINE'  {$$ = {type:'sequenceIndex', sequenceVisible:true, signalType:yy.LINETYPE.AUTONUMBER}; }
| 'activate' actor 'NEWLINE' {$$={type: 'activeStart', signalType: yy.LINETYPE.ACTIVE_START, actor: $2.actor};}
| 'deactivate' actor 'NEWLINE' {$$={type: 'activeEnd', signalType: yy.LINETYPE.ACTIVE_END, actor: $2.actor};}
| note_statement 'NEWLINE'
| links_statement 'NEWLINE'

  bounds.insert(activationData.startx, verticalPos - 10, activationData.stopx, verticalPos);
}

// Draw the messages/signals
let sequenceIndex = 1;
let sequenceIndexStep = 1;
const messagesToDraw = [];
const backgrounds = [];
let index = 0;
for (const msg of messages) {

case diagObj.db.LINETYPE.AUTONUMBER:
  sequenceIndex = msg.message.start || sequenceIndex;
  sequenceIndexStep = msg.message.step || sequenceIndexStep;
  if (msg.message.visible) {
    diagObj.db.enableSequenceNumbers();
  } else {
    diagObj.db.disableSequenceNumbers();
  }
  break;
case diagObj.db.LINETYPE.CRITICAL_START:

  break;
default:
  try {
    msgModel = msg.msgModel;
    msgModel.starty = bounds.getVerticalPos();
    msgModel.sequenceIndex = sequenceIndex;
    msgModel.sequenceVisible = diagObj.db.showSequenceNumbers();
    msgModel.id = msg.id;
    msgModel.from = msg.from;
    msgModel.to = msg.to;
    const lineStartY = await boundMessage(diagram, msgModel);

        bounds.models.addMessage(msgModel);
      } catch (e) {
        log.error('error while drawing message', e);
      }
  }

  // Increment sequence counter if msg.type is a line (and not another event like activation or note, etc)
  if (
    [
      diagObj.db.LINETYPE.SOLID_OPEN,
      diagObj.db.LINETYPE.DOTTED_OPEN,
      diagObj.db.LINETYPE.SOLID,

      diagObj.db.LINETYPE.SOLID_TOP,
      diagObj.db.LINETYPE.SOLID_BOTTOM,
      diagObj.db.LINETYPE.STICK_TOP,
      diagObj.db.LINETYPE.STICK_BOTTOM,

      diagObj.db.LINETYPE.SOLID_TOP_DOTTED,
      diagObj.db.LINETYPE.SOLID_BOTTOM_DOTTED,
      diagObj.db.LINETYPE.STICK_TOP_DOTTED,
      diagObj.db.LINETYPE.STICK_BOTTOM_DOTTED,

      diagObj.db.LINETYPE.SOLID_ARROW_TOP_REVERSE,
      diagObj.db.LINETYPE.SOLID_ARROW_BOTTOM_REVERSE,
      diagObj.db.LINETYPE.STICK_ARROW_TOP_REVERSE,
      diagObj.db.LINETYPE.STICK_ARROW_BOTTOM_REVERSE,

      diagObj.db.LINETYPE.SOLID_ARROW_TOP_REVERSE_DOTTED,
      diagObj.db.LINETYPE.SOLID_ARROW_BOTTOM_REVERSE_DOTTED,
      diagObj.db.LINETYPE.STICK_ARROW_TOP_REVERSE_DOTTED,
      diagObj.db.LINETYPE.STICK_ARROW_BOTTOM_REVERSE_DOTTED,

      diagObj.db.LINETYPE.DOTTED,
      diagObj.db.LINETYPE.SOLID_CROSS,
      diagObj.db.LINETYPE.DOTTED_CROSS,
      diagObj.db.LINETYPE.SOLID_POINT,
      diagObj.db.LINETYPE.DOTTED_POINT,
      diagObj.db.LINETYPE.BIDIRECTIONAL_SOLID,
      diagObj.db.LINETYPE.BIDIRECTIONAL_DOTTED,
    ].includes(msg.type)
  ) {
    // hitting a floating point number error, so round to 2 decimal places
    sequenceIndex = Math.round((sequenceIndex + sequenceIndexStep) * 100) / 100;
  }
  index++;
}

    autonumberX = isLeftToRight ? msgModel.toBounds - 1 : msgModel.fromBounds + 1;
  } else {
    autonumberX = isLeftToRight ? msgModel.fromBounds + 1 : msgModel.toBounds - 1;
  }

  let fontSize = '12px';
  const sequenceIndexLength = sequenceIndex.toString().length;

  if (sequenceIndexLength > 5) {
    fontSize = '7px';
  } else if (sequenceIndexLength > 3) {
    fontSize = '9px';
  }

  diagram
    .append('line')
    .attr('x1', autonumberX)
    .attr('y1', lineStartY)
    .attr('x2', autonumberX)
    .attr('y2', lineStartY)
    .attr('stroke-width', 0)
    .attr('marker-start', 'url(' + url + '#' + diagramId + '-sequencenumber)');

  diagram
    .append('text')
    .attr('x', autonumberX)
    .attr('y', lineStartY + 4)
    .attr('font-family', 'sans-serif')
    .attr('font-size', fontSize)
    .attr('text-anchor', 'middle')
    .attr('class', 'sequenceNumber')
    .text(sequenceIndex);
}

